	@Test
	void largestEncodableImageUsesThe64KiBCapacityClass() {
		int low = 1;
		int high = 20_000;
		CompactCsfPageEncoder.PageImage largest = null;
		while (low <= high) {
			int middle = (low + high) >>> 1;
			CompactCsfPageEncoder.PageImage candidate = tryEncodeFibers(middle);
			if (candidate == null) {
				high = middle - 1;
			} else {
				largest = candidate;
				low = middle + 1;
			}
		}

		assertThat(largest).isNotNull();
		assertThat(largest.capacity()).isEqualTo(64 * 1024);
	}

