	@Test
	void bindTrustedDecodesIdenticallyToFullResolve() {
		CsfPageData data = new CsfPageData();
		data.appendRow(id(1, 1), new long[] { id(1, 10), id(1, 20) }, new int[] { 0, 1 },
				new int[] { 1, 3 }, new long[] { id(2, 100), id(2, 200), id(2, 201), id(2, 202) }, 2, 4);
		data.appendRow(id(1, 2), new long[] { id(1, 30) }, new int[] { 0 }, new int[] { 2 },
				new long[] { id(2, 300), id(2, 301) }, 1, 2);
		data.appendRow(id(1, 3), new long[] { id(1, 40), id(1, 50), id(1, 60) }, new int[] { 0, 1, 3 },
				new int[] { 1, 2, 1 },
				new long[] { id(2, 400), id(2, 500), id(2, 501), id(2, 600) }, 3, 4);
		CompactCsfPageEncoder.PageImage image = new CompactCsfPageEncoder().tryEncode(data, false, 13);

		long address = UnsafeAccess.allocateZeroed(image.capacity() + PackedLongVector.READ_TAIL_PADDING);
		try {
			UnsafeAccess.copyFromArray(image.bytes(), 0, address, image.bytes().length);
			CompactCsfPageReader full = new CompactCsfPageReader();
			full.resolve(address);
			CompactCsfPageReader trusted = new CompactCsfPageReader();
			trusted.bindTrusted(address);

			assertThat(trusted.rowCount()).isEqualTo(full.rowCount());
			assertThat(trusted.fiberCount()).isEqualTo(full.fiberCount());
			assertThat(trusted.quadCount()).isEqualTo(full.quadCount());
			for (int row = 0; row < full.rowCount(); row++) {
				assertThat(trusted.rowAt(row)).isEqualTo(full.rowAt(row));
				int quads = full.rowQuadCount(row);
				long[] fullNeighbors = new long[quads];
				long[] fullContexts = new long[quads];
				long[] trustedNeighbors = new long[quads];
				long[] trustedContexts = new long[quads];
				assertThat(full.copyRow(row, 0, quads, fullNeighbors, 0, fullContexts, 0)).isEqualTo(quads);
				assertThat(trusted.copyRow(row, 0, quads, trustedNeighbors, 0, trustedContexts, 0)).isEqualTo(quads);
				assertThat(trustedNeighbors).containsExactly(fullNeighbors);
				assertThat(trustedContexts).containsExactly(fullContexts);
			}
		} finally {
			UnsafeAccess.free(address);
		}
	}

	@Test
	void pageSlackAcceleratorsNeverChangeTheSelectedNativeCapacityClass() {
		CompactCsfPageEncoder.PageImage image = acceleratedPage();
		int descriptor = LeBytes.getInt(image.bytes(), CompactCsfPageFormat.ACCELERATOR_DESCRIPTOR_AT);
		int acceleratorOffset = LeBytes.getInt(image.bytes(), CompactCsfPageFormat.ACCELERATOR_OFFSET_AT);
		int acceleratorLength = LeBytes.getInt(image.bytes(), CompactCsfPageFormat.ACCELERATOR_LENGTH_AT);

		assertThat(descriptor).isNotZero();
		assertThat(acceleratorLength).isPositive();
		assertThat(acceleratorOffset + acceleratorLength).isEqualTo(image.usedBytes());
		int baselineClass = NativeSlabAllocator.classForUsedBytes(acceleratorOffset);
		assertThat(baselineClass).isEqualTo(image.classIndex());
		assertThat(NativeSlabAllocator.capacityForClass(baselineClass)).isEqualTo(image.capacity());
	}

